def _estimate_context_chars(messages: list) -> int:
    """Stima il numero totale di caratteri nel contesto messaggi.

    Conta TUTTI i contenuti: testo, tool_result.content E tool_use.input.
    La versione precedente ignorava i blocchi tool_use (il campo si chiama
    "input", non "content") e non gestiva m.content quando e' una lista
    (caso AIMessage con blocchi misti text+tool_use). La sottostima causava
    compressione tardiva con conseguente esplosione prompt tokens (448K+
    per run da 47 iterazioni).
    """
    total = 0
    for m in messages:
        content = getattr(m, "content", None)
        if isinstance(content, str):
            total += len(content)
        elif isinstance(content, list):
            # AIMessage.content puo' essere lista di blocchi
            # [{"type":"text","text":"..."}, {"type":"tool_use","input":{...}}]
            for block in content:
                if not isinstance(block, dict):
                    continue
                btype = block.get("type", "")
                if btype == "text":
                    total += len(block.get("text", ""))
                elif btype == "tool_use":
                    inp = block.get("input")
                    if isinstance(inp, dict):
                        total += len(json.dumps(inp, ensure_ascii=False))
                    elif isinstance(inp, str):
                        total += len(inp)
        kwargs = getattr(m, "additional_kwargs", {}) or {}
        for block in kwargs.get("anthropic_content", []):
            if isinstance(block, dict):
                btype = block.get("type", "")
                if btype == "tool_result":
                    c = block.get("content", "")
                    total += len(c) if isinstance(c, str) else 0
