def _sanitize_discovered_schema(schema: Any) -> dict:
    """Normalizza l'input_schema di un tool scoperto a un object JSON-schema
    minimo valido. Droppa $schema/vendor keys; se troppo grande o non-dict,
    ripiega su un object vuoto (il tool resta invocabile per-nome lato mcp-core)."""
    import json as _json
    if not isinstance(schema, dict):
        return {"type": "object", "properties": {}}
    try:
        if len(_json.dumps(schema)) > _discovery_schema_max_bytes():
            return {"type": "object", "properties": {}}
    except Exception:
        return {"type": "object", "properties": {}}
    cleaned = {k: v for k, v in schema.items() if k not in ("$schema", "$id", "definitions", "$defs")}
    if cleaned.get("type") != "object":
        cleaned.setdefault("type", "object")
    cleaned.setdefault("properties", cleaned.get("properties", {}) if isinstance(cleaned.get("properties"), dict) else {})
    return cleaned


def _parse_discovered_from_results(content: str) -> list[dict]:
    """Estrae i tool scoperti dal JSON di nexus_mcp_tool_search.
    Ritorna [{name, description, input_schema}] pronti per tools_json (formato
    Anthropic, gia' traducibile da tool_translator M1). Difensivo: [] su errore."""
    import json as _json
    out: list[dict] = []
    try:
        data = _json.loads(content) if isinstance(content, str) else content
    except Exception:
        return out
    results = (data or {}).get("results") if isinstance(data, dict) else None
    if not isinstance(results, list):
        return out
    seen: set[str] = set()
    for res in results:
        if not isinstance(res, dict):
            continue
        name = res.get("tool_name") or res.get("name")
        if not name or name in seen:
            continue
        seen.add(name)
        out.append({
            "name": name,
            "description": (res.get("description") or "")[:400],
            "input_schema": _sanitize_discovered_schema(res.get("input_schema")),
        })
    return out

